//! Golden test: the converter must keep producing, byte for byte, the blobs it produced for two synthetic A2-Lite models.
//! The `.ref.a2l` fixtures are generated by THIS project's converter (MIT):
//!   cargo run --release -p pulsedeck-core --example nam2a2l -- tests/fixtures/a.nam tests/fixtures/a.ref.a2l   (same for b)
//! Regenerate them only on purpose, when the A2L1 quantisation is changed deliberately.
use pulsedeck_core::a2l::{convert_str, validate_blob, ConvertOptions};

fn check(name: &str) {
    let dir = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/");
    let nam = std::fs::read_to_string(format!("{dir}{name}.nam")).unwrap();
    let want = std::fs::read(format!("{dir}{name}.ref.a2l")).unwrap();
    let got = convert_str(&nam, &ConvertOptions::default()).unwrap().blob;
    validate_blob(&got).unwrap();
    assert_eq!(got.len(), want.len());
    assert!(got == want, "{name}: blob differs from reference");
}

#[test]
fn matches_reference_model_a() {
    check("a");
}

#[test]
fn matches_reference_model_b() {
    check("b");
}
